// ---- i16 pair cross add/subtract (aarch32 DSP `QASX`/`QSAX`/`SASX` equivalents)
//
// A64 has no single instruction for these; they are `REV32` (swap the two
// halves of every 32-bit pair in `b`) plus one add and one subtract, merged
// with `BSL` on an odd-lane mask. Hand-written rather than a DSL rule: the
// op is defined on **pairs**, so the slice form panics on an odd length
// instead of silently treating a trailing element as half a pair - the
// same contract as `aarch32::auto_up::qasx_i16`.

/// One pair-cross op on 8 `i16` lanes: odd lanes get `a[2k+1] ± b[2k]`,
/// even lanes get `a[2k] ∓ b[2k+1]`. `$odd`/`$even` are the two Neon ops.
macro_rules! neon_i16x8_cross {
    ($fixed_fn:ident, $slice_fn:ident, $intrinsic_fn:ident, $odd:path, $even:path, $sodd:expr, $seven:expr, $fixed_doc:literal, $slice_doc:literal $(,)?) => {
        impl Neon {
            #[doc = $fixed_doc]
            #[inline]
            pub fn $fixed_fn(self, a: [i16; 8], b: [i16; 8]) -> [i16; 8] {
                unsafe { $intrinsic_fn(&a, &b) }
            }

            #[doc = $slice_doc]
            ///
            /// # Panics
            /// `a.len() != b.len()`, `out.len() != a.len()`, or an odd length
            /// (the op is defined on whole `[i16; 2]` pairs).
            pub fn $slice_fn(self, a: &[i16], b: &[i16], out: &mut [i16]) {
                assert_eq!(a.len(), b.len());
                assert_eq!(out.len(), a.len());
                assert!(
                    a.len() % 2 == 0,
                    "pair op needs an even length, got {}",
                    a.len()
                );
                let mut ac = a.chunks_exact(8);
                let mut bc = b.chunks_exact(8);
                let mut oc = out.chunks_exact_mut(8);
                for ((x, y), o) in ac.by_ref().zip(bc.by_ref()).zip(oc.by_ref()) {
                    o.copy_from_slice(&unsafe {
                        $intrinsic_fn(x.try_into().unwrap(), y.try_into().unwrap())
                    });
                }
                let odd: fn(i16, i16) -> i16 = $sodd;
                let even: fn(i16, i16) -> i16 = $seven;
                let (ar, br, or) = (ac.remainder(), bc.remainder(), oc.into_remainder());
                for k in 0..ar.len() / 2 {
                    or[2 * k] = even(ar[2 * k], br[2 * k + 1]);
                    or[2 * k + 1] = odd(ar[2 * k + 1], br[2 * k]);
                }
            }
        }

        /// # Safety
        /// Caller proved the feature via the token.
        #[inline]
        #[target_feature(enable = "neon")]
        unsafe fn $intrinsic_fn(a: &[i16; 8], b: &[i16; 8]) -> [i16; 8] {
            unsafe {
                let va: int16x8_t = vld1q_s16(a.as_ptr());
                let vb: int16x8_t = vrev32q_s16(vld1q_s16(b.as_ptr()));
                // Little-endian: in each 32-bit pair the odd `i16` is the high half.
                let odd_lanes: uint16x8_t = vreinterpretq_u16_u32(vdupq_n_u32(0xFFFF_0000));
                let vr = vbslq_s16(odd_lanes, $odd(va, vb), $even(va, vb));
                let mut out = [0i16; 8];
                vst1q_s16(out.as_mut_ptr(), vr);
                out
            }
        }
    };
}

