// ---- composed ops
//
// Ops A64 Neon has no single instruction for, built from two or three that it
// does. Each is a safe `#[target_feature(enable = "neon")]` fn with the same
// signature as the intrinsic it stands in for, so the ordinary DSL rules take
// it as their `intrinsic = ...` unchanged.

macro_rules! compose_minmax_64 {
    ($name:ident, $Vec:ty, $cmp:path, $bsl:path, $pick_a_when_gt:literal) => {
        #[inline]
        #[target_feature(enable = "neon")]
        fn $name(a: $Vec, b: $Vec) -> $Vec {
            // `a > b` lane mask; max keeps `a` there, min keeps `b`.
            if $pick_a_when_gt {
                $bsl($cmp(a, b), a, b)
            } else {
                $bsl($cmp(a, b), b, a)
            }
        }
    };
}
compose_minmax_64!(compose_max_s64q, int64x2_t, vcgtq_s64, vbslq_s64, true);
compose_minmax_64!(compose_min_s64q, int64x2_t, vcgtq_s64, vbslq_s64, false);
compose_minmax_64!(compose_max_u64q, uint64x2_t, vcgtq_u64, vbslq_u64, true);
compose_minmax_64!(compose_min_u64q, uint64x2_t, vcgtq_u64, vbslq_u64, false);

/// `CNT` counts bits per byte; each `UADDLP` sums adjacent lanes into the
/// next wider width.
#[inline]
#[target_feature(enable = "neon")]
fn compose_popcnt_u16q(a: uint16x8_t) -> uint16x8_t {
    vpaddlq_u8(vcntq_u8(vreinterpretq_u8_u16(a)))
}
#[inline]
#[target_feature(enable = "neon")]
fn compose_popcnt_u32q(a: uint32x4_t) -> uint32x4_t {
    vpaddlq_u16(vpaddlq_u8(vcntq_u8(vreinterpretq_u8_u32(a))))
}
#[inline]
#[target_feature(enable = "neon")]
fn compose_popcnt_u64q(a: uint64x2_t) -> uint64x2_t {
    vpaddlq_u32(vpaddlq_u16(vpaddlq_u8(vcntq_u8(vreinterpretq_u8_u64(a)))))
}

// FMA sign variants, in the accumulator-first shape `neon_fma!` calls
// (`intrinsic(c, a, b)`). Negating a result is exact, so each stays a single
// rounding: `a·b - c = -(c - a·b)` and `-(a·b) - c = -(c + a·b)`.
macro_rules! compose_fma_neg {
    ($name:ident, $Vec:ty, $inner:path, $neg:path) => {
        #[inline]
        #[target_feature(enable = "neon")]
        fn $name(c: $Vec, a: $Vec, b: $Vec) -> $Vec {
            $neg($inner(c, a, b))
        }
    };
}
compose_fma_neg!(compose_fmsub_f32q, float32x4_t, vfmsq_f32, vnegq_f32);
compose_fma_neg!(compose_fmsub_f64q, float64x2_t, vfmsq_f64, vnegq_f64);
compose_fma_neg!(compose_fmsub_f32d, float32x2_t, vfms_f32, vneg_f32);
compose_fma_neg!(compose_fnmsub_f32q, float32x4_t, vfmaq_f32, vnegq_f32);
