// ---- f16 <-> f32 conversion (baseline ARMv8, no FEAT_FP16)
//
// `FCVTL`/`FCVTN` have been in the base FP/SIMD ISA since ARMv8.0; only
// half-precision *arithmetic* needs FEAT_FP16. On aarch64, stdarch's
// `vcvt_f32_f16`/`vcvt_f16_f32` only need `neon` (the `fp16` gate applies to
// 32-bit Arm only), so plain Neon covers them. That is what lets the `auto`
// layer offer `f16` ops on every AArch64 CPU (see `auto_down`). Lanes are
// moved as `u16` and reinterpreted, because `vld1_f16` is still unstable.

impl Neon {
    /// Widen four IEEE binary16 bit patterns to `f32`. Exact - every `f16` is
    /// representable in `f32` (`fcvtl v.4s, v.4h`).
    #[inline]
    pub fn cvt_f16x4_to_f32x4(self, a: [u16; 4]) -> [f32; 4] {
        unsafe { fcvtl_f16d_fixed(&a) }
    }

    /// Narrow four `f32` to binary16 bit patterns, round-to-nearest-even,
    /// overflow to ±∞ (`fcvtn v.4h, v.4s`).
    #[inline]
    pub fn cvt_f32x4_to_f16x4(self, a: [f32; 4]) -> [u16; 4] {
        unsafe { fcvtn_f32q_fixed(&a) }
    }

    /// [`Neon::cvt_f16x4_to_f32x4`] over whole slices; the tail goes through
    /// the same instruction on a zero-padded chunk.
    ///
    /// # Panics
    /// `out.len() != a.len()`.
    pub fn cvt_f16_to_f32_slice(self, a: &[u16], out: &mut [f32]) {
        assert_eq!(out.len(), a.len());
        let whole = a.len() - a.len() % 4;
        for i in (0..whole).step_by(4) {
            out[i..i + 4]
                .copy_from_slice(&unsafe { fcvtl_f16d_fixed(a[i..i + 4].try_into().unwrap()) });
        }
        if whole < a.len() {
            let mut pad = [0u16; 4];
            pad[..a.len() - whole].copy_from_slice(&a[whole..]);
            let r = unsafe { fcvtl_f16d_fixed(&pad) };
            out[whole..].copy_from_slice(&r[..a.len() - whole]);
        }
    }

    /// [`Neon::cvt_f32x4_to_f16x4`] over whole slices; padded tail as above.
    ///
    /// # Panics
    /// `out.len() != a.len()`.
    pub fn cvt_f32_to_f16_slice(self, a: &[f32], out: &mut [u16]) {
        assert_eq!(out.len(), a.len());
        let whole = a.len() - a.len() % 4;
        for i in (0..whole).step_by(4) {
            out[i..i + 4]
                .copy_from_slice(&unsafe { fcvtn_f32q_fixed(a[i..i + 4].try_into().unwrap()) });
        }
        if whole < a.len() {
            let mut pad = [0f32; 4];
            pad[..a.len() - whole].copy_from_slice(&a[whole..]);
            let r = unsafe { fcvtn_f32q_fixed(&pad) };
            out[whole..].copy_from_slice(&r[..a.len() - whole]);
        }
    }
}

/// # Safety
/// Caller proved Neon via the token.
#[inline]
#[target_feature(enable = "neon")]
unsafe fn fcvtl_f16d_fixed(a: &[u16; 4]) -> [f32; 4] {
    use super::super::simd_arch::{vcvt_f32_f16, vld1_u16, vreinterpret_f16_u16};
    let mut out = [0f32; 4];
    unsafe {
        vst1q_f32(
            out.as_mut_ptr(),
            vcvt_f32_f16(vreinterpret_f16_u16(vld1_u16(a.as_ptr()))),
        )
    };
    out
}

/// # Safety
/// Caller proved Neon via the token.
#[inline]
#[target_feature(enable = "neon")]
unsafe fn fcvtn_f32q_fixed(a: &[f32; 4]) -> [u16; 4] {
    use super::super::simd_arch::{vcvt_f16_f32, vreinterpret_u16_f16, vst1_u16};
    let mut out = [0u16; 4];
    unsafe {
        vst1_u16(
            out.as_mut_ptr(),
            vreinterpret_u16_f16(vcvt_f16_f32(vld1q_f32(a.as_ptr()))),
        )
    };
    out
}
